const $ = id => document.getElementById(id);
const SAVE_KEY = 'woojin-game-v1', MAX = 1e300, OFFLINE_CAP = 8 * 3600;
const items = [{"icon": "🍪", "name": "바삭 쿠키", "base": 20, "type": "click", "power": 1, "unlock": 1}, {"icon": "🍔", "name": "든든 버거", "base": 250, "type": "click", "power": 100, "unlock": 2}, {"icon": "🧋", "name": "달콤한 버블티", "base": 25000, "type": "auto", "power": 5000, "unlock": 3}, {"icon": "🍕", "name": "피자 파티", "base": 2500000, "type": "auto", "power": 500000, "unlock": 4}, {"icon": "🍩", "name": "초코 도넛", "base": 250000000, "type": "click", "power": 20000000, "unlock": 5}, {"icon": "🍜", "name": "야식 라멘", "base": 25000000000, "type": "auto", "power": 5000000000, "unlock": 6}, {"icon": "🍱", "name": "특제 도시락", "base": 2500000000000, "type": "click", "power": 200000000000, "unlock": 7}, {"icon": "🎂", "name": "축하 케이크", "base": 250000000000000, "type": "auto", "power": 50000000000000, "unlock": 8}];
const questDefs=[['tap100','터치 트레이닝','톡톡 탐험가',100,2,150,s=>s.taps],['tap1000','연타 챌린지','연타의 달인',1000,2,2000,s=>s.taps],['buy10','간식 수집가','간식 단골',10,1.6,300,s=>s.counts.reduce((a,b)=>a+b,0)],['level5','성장의 기록','든든한 친구',5,1.4,800,s=>level(s)],['fever5','피버 챌린지','피버 마스터',5,1.8,1800,s=>s.fevers]];
function questTier(a,s=state){return s.questTiers?.[a.id]||0}
function questGoal(a,s=state){return Math.min(MAX,Math.ceil(a.base*a.growth**questTier(a,s)))}
function questReward(a){return Math.min(MAX,Math.ceil(a.reward*1.8**questTier(a)))}
const achievements=questDefs.map(([id,name,title,base,growth,reward,metric])=>({id,name,title,base,growth,reward,metric,test:s=>metric(s)>=questGoal({id,base,growth},s),progress:s=>format(metric(s))+' / '+format(questGoal({id,base,growth},s))}));
const oldThresholds=[0,40,160,450,1100,2500,5500,12000,26000,55000,115000,240000];
const fresh=()=>({version:5,levelOrigin:1,levelAnchor:0,levelStep:10000,unlocked:items.map((_,i)=>i===0),questTiers:{},points:0,total:0,counts:items.map(()=>0),sound:true,taps:0,fevers:0,claimed:[],title:'말랑말랑 새싹',selectedPhoto:0,autoPhoto:true,highestLevel:1,lastSaved:Date.now()});
const nonnegative=(v,fallback=0)=>Number.isFinite(v)&&v>=0?Math.min(v,MAX):fallback;
function load(){let raw;try{raw=JSON.parse(localStorage.getItem(SAVE_KEY))}catch{};if(!raw||typeof raw!=='object')return fresh();const s=fresh();s.points=nonnegative(raw.points);s.total=Math.max(s.points,nonnegative(raw.total));if(Array.isArray(raw.counts))s.counts=items.map((_,i)=>Math.floor(nonnegative(raw.counts[i])));s.unlocked=items.map((_,i)=>i===0||s.counts[i]>0||raw.unlocked?.[i]===true);s.questTiers=Object.fromEntries(achievements.map(a=>[a.id,Math.floor(nonnegative(raw.questTiers?.[a.id],raw.claimed?.includes(a.id)?1:0))]));s.sound=typeof raw.sound==='boolean'?raw.sound:true;s.taps=Math.floor(nonnegative(raw.taps));s.fevers=Math.floor(nonnegative(raw.fevers));s.claimed=Array.isArray(raw.claimed)?raw.claimed.filter(id=>achievements.some(a=>a.id===id)):[];s.title=typeof raw.title==='string'?raw.title:s.title;s.selectedPhoto=Math.min(31,Math.floor(nonnegative(raw.selectedPhoto)));s.autoPhoto=raw.autoPhoto!==false;s.lastSaved=nonnegative(raw.lastSaved,Date.now());let previous=1;if(!raw.version||raw.version<2){oldThresholds.forEach((t,i)=>{if(s.total>=t)previous=i+1})}if(raw.version===3){let oldLevel=1;while(oldLevel<300&&s.total>=100*Math.pow(1.75,oldLevel-1))oldLevel++;previous=Math.max(previous,oldLevel)}s.highestLevel=Math.max(previous,Math.min(300,Math.floor(nonnegative(raw.highestLevel,1))));if(raw.version!==5){if(raw.version===4){let v=1;while(v<300&&s.total>=350*Math.pow(1.95,v-1))v++;s.highestLevel=Math.max(s.highestLevel,v)}s.levelOrigin=s.highestLevel;s.levelAnchor=s.total;const rate=items.reduce((n,x,i)=>n+production(i,s.counts[i])*(x.type==='click'?4:1),4);s.levelStep=Math.min(MAX,Math.max(10000,rate*300))}else{s.levelOrigin=Math.max(1,Math.min(300,Math.floor(nonnegative(raw.levelOrigin,1))));s.levelAnchor=nonnegative(raw.levelAnchor);s.levelStep=Math.max(10000,nonnegative(raw.levelStep,10000))}return s}
let state=load(), feverUntil=0, snackUntil=0, nextSnack=Date.now()+randomDelay(), audio, toastTimer, saveTimer, lastFrame=performance.now(), bounceEnergy=0, lastDraw='', lastFeverSeconds=-1;
function randomDelay(){return 90000}
function threshold(l){return Math.min(MAX,state.levelAnchor+state.levelStep*Math.pow(100,l-state.levelOrigin))}
function level(s=state){let l=Math.max(1,s.highestLevel||1);while(l<300&&s.total>=threshold(l))l++;return l}
function nextThreshold(l){return threshold(l)}
function format(n){if(!Number.isFinite(n))return '∞';n=Math.max(0,Math.floor(n));const units=['','만','억','조','경','해','자','양','구','간','정','재','극'];if(n<10000)return String(n);const income=typeof state==='undefined'?1:Math.max(power('click'),power('auto'),1);const low=Math.max(0,Math.floor(Math.log10(income)/4));const top=Math.min(units.length-1,Math.floor(Math.log10(n)/4));const floor=Math.min(low,Math.max(0,top-1));let parts=[];for(let i=top;i>=floor;i--){const v=Math.floor(n/Math.pow(10000,i))%10000;if(v)parts.push(v+units[i])}return parts.join(' ')||'0'}
const plus=(a,b)=>Math.min(MAX,a+b);
function production(i,count){return Math.min(MAX,Math.round(items[i].power*Math.expm1(Math.min(690,count*Math.log(1.3)))/.3))}
function power(type){return items.reduce((sum,x,i)=>plus(sum,x.type===type?production(i,state.counts[i]):0),type==='click'?1:0)}
function nextEffect(i){return Math.max(0,production(i,state.counts[i]+1)-production(i,state.counts[i]))}
function effectText(i){return (items[i].type==='click'?'터치 +':'초당 +')+format(nextEffect(i))+'원'}
function unlockCost(i){return Math.min(MAX,items[i].base*12)}
function cost(i){return Math.min(MAX,Math.ceil(items[i].base*Math.pow(2.25,state.counts[i])))}
function save(){if(!saveTimer)saveTimer=setTimeout(()=>{saveTimer=null;saveNow()},250)}
function saveNow(){state.lastSaved=Date.now();try{localStorage.setItem(SAVE_KEY,JSON.stringify(state))}catch{toast('기록을 저장하지 못했어. 브라우저 저장 공간을 확인해줘.')}}
window.addEventListener('pagehide',saveNow);
let awayAt=state.lastSaved;
function applyAway(){const elapsed=Math.min(OFFLINE_CAP,Math.max(0,(Date.now()-awayAt)/1000));if(elapsed>2&&power('auto')>0){const amount=Math.min(MAX,power('auto')*Math.floor(elapsed));gain(amount,false);toast('자리 비운 동안 +'+format(amount)+'원 획득!')}awayAt=Date.now()}
document.addEventListener('visibilitychange',()=>{if(document.hidden){awayAt=Date.now();saveNow()}else{applyAway();tick=Date.now();lastFrame=performance.now()}});
